export const SV_MAP_CSS = "/*\n * SV Map styles. Make it look like your app by setting these variables on the map's\n * element (or any parent), e.g.\n *\n *   #map { --svm-brand: #2563eb; --svm-radius: 8px; --svm-height: 70vh; }\n *\n * Dark mode follows the device unless you set data-theme=\"light\" / \"dark\" on the element.\n */\n.svm {\n  --svm-brand: #0f6b5c;        /* pins, active chip */\n  --svm-brand-ink: #ffffff;    /* text on the brand colour */\n  --svm-highlight: #c08a1e;    /* \"mine\" pins */\n  --svm-ok: #1f7a4a;  --svm-ok-soft: #e5f4ea;\n  --svm-warn: #9a5b00; --svm-warn-soft: #fff3dc;\n  --svm-surface: #ffffff;      /* sheet, chips, buttons */\n  --svm-surface-2: #f3eee6;    /* quiet fills */\n  --svm-ink: #1d2321;          /* text */\n  --svm-muted: #6e7a75;        /* secondary text */\n  --svm-line: #e4ddd2;         /* borders */\n  --svm-focus: #f5b301;        /* keyboard focus ring */\n  --svm-radius: 14px;\n  --svm-height: min(64vh, 560px);\n  --svm-font: inherit;\n  --svm-shadow: 0 1px 2px rgba(0,0,0,.06), 0 6px 20px rgba(0,0,0,.08);\n  position: relative;\n  font-family: var(--svm-font);\n  color: var(--svm-ink);\n}\n@media (prefers-color-scheme: dark) {\n  .svm:not([data-theme=\"light\"]) {\n    --svm-surface: #18201d; --svm-surface-2: #1f2925; --svm-ink: #ecf2ef; --svm-muted: #8c9a94; --svm-line: #2b3632;\n    --svm-brand: #3fb59d; --svm-brand-ink: #08221c; --svm-ok: #6fd39c; --svm-ok-soft: #173526; --svm-warn: #f2b45a; --svm-warn-soft: #3a2c14;\n    --svm-shadow: 0 1px 2px rgba(0,0,0,.3);\n  }\n}\n.svm[data-theme=\"dark\"] {\n  --svm-surface: #18201d; --svm-surface-2: #1f2925; --svm-ink: #ecf2ef; --svm-muted: #8c9a94; --svm-line: #2b3632;\n  --svm-brand: #3fb59d; --svm-brand-ink: #08221c; --svm-ok: #6fd39c; --svm-ok-soft: #173526; --svm-warn: #f2b45a; --svm-warn-soft: #3a2c14;\n}\n.svm *, .svm *::before, .svm *::after { box-sizing: border-box; }\n.svm button { font: inherit; }\n.svm :focus-visible { outline: 3px solid var(--svm-focus); outline-offset: 2px; }\n\n.svm-skip { position: absolute; left: -9999px; }\n.svm-skip:focus { left: 8px; top: 8px; z-index: 6; background: var(--svm-surface); color: var(--svm-ink); padding: 8px 12px; border-radius: 10px; border: 2px solid var(--svm-brand); }\n\n/* chips */\n.svm-chips { display: flex; gap: 6px; overflow-x: auto; padding: 2px 2px 8px; scrollbar-width: none; }\n.svm-chips::-webkit-scrollbar { display: none; }\n.svm-chip { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 4px; min-height: 40px; padding: 0 14px; border-radius: 999px;\n  border: 1px solid var(--svm-line); background: var(--svm-surface); color: var(--svm-ink); font-size: .88rem; font-weight: 600; cursor: pointer; }\n.svm-chip.on { background: var(--svm-brand); border-color: var(--svm-brand); color: var(--svm-brand-ink); }\n\n/* the map box */\n.svm-map { position: relative; height: var(--svm-height); min-height: 320px; border-radius: var(--svm-radius); overflow: hidden;\n  border: 1px solid var(--svm-line); background: var(--svm-surface-2); }\n/* MapLibre sets position: relative on its container; keep it filling the box. */\n.svm-canvas.svm-canvas { position: absolute; inset: 0; width: 100%; height: 100%; }\n.svm-fallback { position: absolute; inset: auto 12px 12px; z-index: 3; margin: 0; padding: 10px 12px; border-radius: 10px; background: var(--svm-warn-soft); color: var(--svm-warn); }\n.svm-me { position: absolute; right: 10px; bottom: 12px; z-index: 3; width: 46px; height: 46px; border-radius: 50%; border: 1px solid var(--svm-line);\n  background: var(--svm-surface); color: var(--svm-brand); font-size: 1.3rem; cursor: pointer; box-shadow: var(--svm-shadow); }\n.svm-count { margin: 6px 2px 0; color: var(--svm-muted); font-size: .86rem; }\n.svm .maplibregl-ctrl-attrib { font-size: .7rem; }\n\n/* key */\n.svm-key { position: absolute; left: 10px; bottom: 12px; z-index: 3; max-width: 62%; padding: 6px 10px; border-radius: 12px; font-size: .8rem;\n  background: color-mix(in srgb, var(--svm-surface) 94%, transparent); border: 1px solid var(--svm-line); box-shadow: var(--svm-shadow); }\n.svm-key summary { cursor: pointer; font-weight: 600; min-height: 28px; }\n.svm-key p { margin: 2px 0; display: flex; align-items: center; gap: 6px; }\n.svm-k { display: inline-grid; place-items: center; width: 16px; height: 16px; border-radius: 50%; font-style: normal; font-size: 10px; flex: 0 0 auto; }\n.svm-k.exact { background: var(--svm-brand); border: 2px solid #fff; box-shadow: 0 0 0 1px var(--svm-brand); }\n.svm-k.area { border: 2px dashed var(--svm-brand); background: color-mix(in srgb, var(--svm-brand) 18%, transparent); }\n.svm-k.highlight { background: var(--svm-highlight); color: #fff; }\n.svm-k.swatch { border-radius: 4px; }\n\n/* pins */\n.svm-pin { position: relative; display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: 7px; padding: 0; border-radius: 50%;\n  border: 2px solid #fff; background: var(--svm-brand); color: var(--svm-brand-ink); font-weight: 700; cursor: pointer; box-shadow: 0 3px 10px rgba(0,0,0,.28); }\n.svm-pin > span { font-size: 18px; line-height: 1; }\n.svm-pin::after { content: \"\"; position: absolute; left: 50%; bottom: -8px; transform: translateX(-50%); border: 6px solid transparent; border-top: 7px solid #fff; border-bottom: 0; }\n.svm-pin.area { border: 2px dashed var(--svm-brand); background: color-mix(in srgb, var(--svm-surface) 82%, var(--svm-brand)); color: var(--svm-ink); }\n.svm-pin.muted { opacity: .7; }\n.svm-pin.highlight { background: var(--svm-highlight); color: #fff; }\n.svm-pin i { position: absolute; top: -6px; right: -6px; width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center;\n  background: var(--svm-ok); color: #fff; font-style: normal; font-size: 11px; border: 2px solid #fff; }\n.svm-pin:focus-visible { outline-offset: 3px; }\n.svm-dot { width: 18px; height: 18px; border-radius: 50%; background: #2563eb; border: 3px solid #fff; box-shadow: 0 0 0 6px rgba(37,99,235,.25); }\n\n/* sheet */\n.svm-sheet { position: absolute; left: 8px; right: 8px; bottom: 8px; z-index: 4; max-height: 62%; overflow: auto; padding: 14px 14px 8px;\n  border-radius: 16px; background: var(--svm-surface); border: 1px solid var(--svm-line); box-shadow: 0 -6px 30px rgba(0,0,0,.18); }\n.svm-sheet-h { margin: 0 40px 8px 0; font-size: 1.05rem; line-height: 1.35; }\n.svm-sheet-h:focus { outline: none; }\n.svm-x { position: absolute; top: 6px; right: 6px; width: 44px; height: 44px; border: 0; border-radius: 50%; background: none; color: var(--svm-muted); font-size: 1.1rem; cursor: pointer; }\n.svm-card { display: flex; gap: 10px; padding: 10px 4px; border-top: 1px solid var(--svm-line); color: inherit; text-decoration: none; }\n.svm-card:first-child { border-top: 0; }\n.svm-card-media { flex: 0 0 auto; font-size: 1.6rem; line-height: 1.2; }\n.svm-card-media img { display: block; width: 56px; height: 56px; object-fit: cover; border-radius: 10px; }\n.svm-card-text { display: flex; flex-direction: column; gap: 1px; min-width: 0; }\n.svm-card b { font-size: .98rem; }\n.svm-card small { color: var(--svm-muted); font-size: .84rem; }\n.svm-badges em { font-style: normal; padding: 1px 8px; border-radius: 999px; background: var(--svm-surface-2); color: var(--svm-ink); }\n.svm-badges em.ok { background: var(--svm-ok-soft); color: var(--svm-ok); }\n.svm-badges em.warn { background: var(--svm-warn-soft); color: var(--svm-warn); }\n.svm-badges em.accent { background: color-mix(in srgb, var(--svm-brand) 16%, transparent); color: var(--svm-brand); }\n.svm-badges em.muted { opacity: .75; }\n.svm-note { font-style: italic; }\n\n/* wide screens: the sheet is a side panel */\n@media (min-width: 900px) {\n  .svm-sheet { left: auto; right: 12px; top: 12px; bottom: auto; width: 360px; max-height: calc(100% - 24px); }\n}\n@media (prefers-reduced-motion: reduce) {\n  .svm * { transition: none !important; animation: none !important; }\n}\n";
